SELECT id, store_name, city, region, opened_date, RANK() OVER (ORDER BY sqft DESC NULLS FIRST) AS sqft_rank, AVG(sqft) OVER w_running AS sqft_avg_2, DENSE_RANK() OVER (PARTITION BY city ORDER BY sqft) AS sqft_dense_rank, SUM(sqft) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft, SUM(sqft) OVER (PARTITION BY city, region) AS city_sum_sqft FROM stores WHERE opened_date >= '2025-05-26' WINDOW w_running AS (ORDER BY sqft, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
